actions.script:
String tenantId = ownerFields?.companyUserGroupId as String
String active = darpan.facade.common.TenantAccessSupport.currentActiveTenantUserGroupId(ec)
if (!tenantId) { problem = 'A query belongs to a tenant: companyUserGroupId is required.'; return }
if (!active || tenantId != active) { problem = "A query can be stored only for your active tenant, not ${tenantId}.".toString(); return }

Map out = darpan.query.QueryDelivery.chat(ec, [scriptDeployment: scriptDeployment, delivery: delivery, scriptResult: scriptResult, files: files])
if (out.error) { ec.message.addError(out.error as String); return }
outcome = out.outcome; message = out.message
